function printReceipt(a,w=null){
 const x=Array.isArray(a)?a[0]:a;if(!x)return false;
 w=w&&!w.closed?w:window.open('about:blank','society360-payment-receipt','width=850,height=760');
 if(!w){notify('Payment saved, but the receipt popup was blocked. Allow popups and open the receipt from payment history.','error');return false}
 const locale=window.Society360I18n?.locale?.()||'en-IN';
 const money=v=>new Intl.NumberFormat(locale,{style:'currency',currency:'INR',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0));
 const dateTime=v=>{if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeStyle:'short'}).format(d)};
 const rows=[[trw('Receipt Number'),x.receipt_no],[trw('Receipt Date / Time'),dateTime(x.receipt_date)],[trw('Payment Status'),trw(x.payment_status||'Success')],[trw('Consumer'),x.customer_name],[trw('Consumer Number'),x.customer_code||x.consumer_no],[trw('Flat / Wing'),String(x.flat_no||'')+' / '+String(x.wing_name||'')],[trw('Payment Date'),dateTime(x.payment_date)],[trw('Payment Mode'),trw(x.payment_mode||'')],[trw('Reference'),x.reference_no],[trw('Amount Received'),money(x.amount)]];
 const asArray=v=>{if(Array.isArray(v))return v;if(typeof v==='string'){try{const parsed=JSON.parse(v);return Array.isArray(parsed)?parsed:[]}catch{}}return []};
 const items=asArray(x.charge_breakdown);
 const allocations=asArray(x.bill_allocations);
 const chargeHtml=items.length?'<h2>'+trw('Charge Breakdown')+'</h2><table><thead><tr><td>'+trw('Charge')+'</td><td>'+trw('Amount')+'</td></tr></thead><tbody>'+items.map(i=>'<tr><td>'+esc(trw(i.label||''))+'</td><td>'+esc(money(i.amount))+'</td></tr>').join('')+'<tr><td><strong>'+trw('Total Allocated')+'</strong></td><td><strong>'+esc(money(items.reduce((s,i)=>s+Number(i.amount||0),0)))+'</strong></td></tr></tbody></table>':'<p>'+trw('No itemized bill allocation is available for this payment.')+'</p>';
 const billHtml=allocations.length?'<h2>'+trw('Bill Allocations')+'</h2><table><thead><tr><td>'+trw('Bill Number')+'</td><td>'+trw('Billing Period')+'</td><td>'+trw('Allocated')+'</td></tr></thead><tbody>'+allocations.map(b=>'<tr><td>'+esc(b.bill_no||'')+'</td><td>'+esc(b.bill_month||'')+'</td><td>'+esc(money(b.allocated_amount))+'</td></tr>').join('')+'</tbody></table>':'';
 const societyMeta=[x.society_address,x.society_phone,x.society_email].filter(Boolean).map(esc).join(' · ');
 w.document.open();
 w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+esc(trw('Payment Receipt'))+' '+esc(x.receipt_no||'')+'</title><style>body{font:14px Arial,sans-serif;max-width:780px;margin:24px auto;color:#172033}header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #1f456e;padding-bottom:14px}h1{font-size:23px;margin:0}h2{font-size:18px;margin-top:24px}p.meta{color:#536174;margin:8px 0}table{border-collapse:collapse;width:100%;margin-top:12px}td{border-bottom:1px solid #dbe2ea;padding:9px}td:first-child{color:#536174;width:38%}.amount{font-size:20px;font-weight:bold}.print{margin:18px 0;padding:9px 16px}@media print{.print{display:none}body{margin:0}}</style></head><body><header><div><h1>'+esc(x.society_name||'Society360')+'</h1><p class="meta">'+societyMeta+'</p></div>'+(x.society_logo?'<img alt="Society logo" src="'+esc(x.society_logo)+'" style="max-width:80px;max-height:80px">':'')+'</header><h2>'+trw('Payment Receipt')+'</h2><table>'+rows.filter(r=>r[1]!==null&&r[1]!==undefined&&String(r[1])!=='').map(r=>'<tr><td>'+esc(r[0])+'</td><td class="'+(r[0]===trw('Amount Received')?'amount':'')+'">'+esc(r[1])+'</td></tr>').join('')+'</table>'+chargeHtml+billHtml+'<button class="print" onclick="window.print()">'+trw('Print / Save as PDF')+'</button><script>window.focus()<\\/script></body></html>');
 w.document.close();w.focus();return true
}
